import {active} from './workflow.js';
import {STATUS,SELLER_STATUS,SOURCES,REASONS,MODULES,MENUS,SETTINGS,PROCESS,statusOf,agentNames,projectNames,seedCRM,applyCRM,parseCSV} from './crm.js';

let clock=new Date().toISOString(),store=seedCRM(clock),view='Dashboard',dash='D1',role='Manager',filter={},statusFilter='All',page=1,pageSize=10,settingsTab='users',processTab='RNR',reportTab='Logs',noticeCategory='All',dark=false;
let pendingCSV=[],pendingBulk=null;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(v||0);
const fmt=v=>v?new Date(v).toLocaleString('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
const day=v=>v?new Date(v).toLocaleDateString('en-IN'):'—';
const local=v=>{if(!v)return '';const d=new Date(v);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
const later=h=>new Date(Date.parse(clock)+h*3600000).toISOString();
const today=()=>clock.slice(0,10);
const users=()=>agentNames(store),projects=()=>projectNames(store);
const task=l=>store.tasks.find(t=>t.leadId===l.id&&t.status==='Open');
const overdue=l=>task(l)&&Date.parse(task(l).due)<Date.parse(clock);
const visible=r=>role==='Manager'||r.owner===role||r.coOwner===role||r.employee===role;
const allLeads=()=>store.leads.filter(visible);
const byId=id=>store.leads.find(l=>l.id===id);
const selectOptions=(values,value='',blank='Select…')=>`${blank!==null?`<option value="">${esc(blank)}</option>`:''}${values.map(v=>{const [val,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(val)}" ${val===value?'selected':''}>${esc(label)}</option>`;}).join('')}`;
function field(label,name,value='',type='text',required=false,choices=null){return `<label class="field ${type==='textarea'?'full':''}"><span>${esc(label)}${required?' <b>*</b>':''}</span>${choices?`<select name="${name}" ${required?'required':''}>${selectOptions(choices,value,required?'Select…':'All / none')}</select>`:type==='textarea'?`<textarea name="${name}" ${required?'required minlength="3"':''}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="any"':''}>`}</label>`;}
const button=(label,action,id='',cls='')=>`<button type="button" class="${cls}" aria-label="${action==='theme'?'Toggle theme':action==='notifications'?'Notifications':esc(label)}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const nav=(label,target)=>`<button type="button" data-view="${esc(target)}" class="${view===target?'selected':''}">${esc(label)}</button>`;
const statusBadge=value=>`<span class="badge ${['Booked','Verified','Approved','Completed','Active','Available'].includes(value)?'good':['Not Interested','RNR','Rejected','Overdue'].includes(value)?'warn':''}">${esc(value)}</span>`;
const noteField=()=>field('Notes','notes','','textarea',true);
const nextField=v=>field('Next Follow-Up Date','next',local(v||later(24)),'datetime-local',true);
function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.hidden=true,5000);}
function openDialog(title,subtitle,html,wide=false){modal.className=wide?'wide-dialog':'';modal.innerHTML=`<div class="dialog-head"><div><h2 id="dialog-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div>${button('×','dismiss','','icon-button')}</div><div class="dialog-body">${html}</div>`;modal.setAttribute('aria-labelledby','dialog-title');modal.querySelector('[data-action=dismiss]').setAttribute('aria-label','Close dialog');if(!modal.open)modal.showModal();modal.scrollTop=0;}
function run(action,showLead=false){const result=applyCRM(store,action,clock,role);store=result.state;modal.close();render();notify(result.message);if(showLead&&byId(result.resultId)&&visible(byId(result.resultId)))leadDetail(result.resultId);return result;}
function form(title,subtitle,fields,onSubmit,label='Submit',wide=true){openDialog(title,subtitle,`<form id="edit-form"><div class="form-grid">${fields}</div><div class="form-error" role="alert"></div><div class="form-footer">${button('Cancel','dismiss')}<button class="primary" type="submit">${label}</button></div></form>`,wide);modal.querySelector('form').addEventListener('submit',e=>{e.preventDefault();try{onSubmit(Object.fromEntries(new FormData(e.currentTarget)));}catch(error){modal.querySelector('.form-error').textContent=error.message;}});}
function title(name,description='',actions=''){return `<div class="page-heading"><div><h1>${esc(name)}</h1>${description?`<p>${esc(description)}</p>`:''}</div><div class="actions">${actions}</div></div>`;}
function empty(text='No records match this view.'){return `<div class="empty">${esc(text)}</div>`;}
function shell(html){app.innerHTML=`<header class="topbar"><button class="brand" data-view="Dashboard" aria-label="Dashboard"><span class="brand-icon">H</span><span>Home Locator<small>CRM DEMO</small></span></button><nav aria-label="CRM modules">${MENUS.map(([name,target])=>Array.isArray(target)?`<details class="menu"><summary>${name} <span>⌄</span></summary><div class="menu-items">${target.map(([n,t])=>nav(n,t)).join('')}</div></details>`:nav(name,target)).join('')}</nav><div class="top-actions">${button(dark?'☀':'◐','theme','','icon-button')}${button('◎','notifications','','icon-button')}${button('Profile','profile')}</div></header><div class="dashboard-rail" aria-label="Dashboard shortcuts">${['D1','D2','D3','D4'].map((d,i)=>`<button title="${['Overview','Calls and daily leads','Site visits','Missed follow-ups'][i]}" data-dashboard="${d}" class="${view==='Dashboard'&&dash===d?'selected':''}">${d}</button>`).join('')}</div><div class="tools-rail" aria-label="CRM tools">${[['Knowledge Base','Knowledge','▣'],['Inventory','inventory','◇'],['Reports','Reports','▥'],['Settings','Settings','⚙'],['Follow Ups','Follow Ups','◷'],['Search Leads','Search','⌕'],['Workflow Logic','Workflow','⑂']].map(([n,v,icon])=>`<button title="${n}" aria-label="${n}" data-view="${v}">${icon}</button>`).join('')}</div><main><div class="context-bar"><span class="demo-label">INDEPENDENT DEMO · FICTIONAL DATA</span><span>Demo time: ${fmt(clock)} ${button('+1 day','advance','','compact')}</span><label>View as <select id="role" aria-label="View as">${selectOptions(['Manager',...users()],role,null)}</select></label></div>${html}<footer>Session-only demo · Refresh resets changes · No ClientFirst connection · External messages and registrations are drafts only. ${button('Reset demo','reset','','text-button')}</footer></main>`;document.documentElement.dataset.theme=dark?'dark':'light';}
function statusChips(rows,kind='Leads'){const statuses=kind==='Leads'?STATUS:SELLER_STATUS;return `<div class="status-strip">${['All',...statuses].map(s=>{const n=s==='All'?rows.length:rows.filter(r=>(kind==='Leads'?statusOf(r):r.status||'Initial')===s).length;return `<button class="status-chip ${statusFilter===s?'selected':''}" data-status="${esc(s)}"><span>${s}</span><strong>${n}</strong></button>`;}).join('')}</div>`;}
function matches(r){const hay=[r.name,r.phone,r.email,r.id,r.project,r.unit].join(' ').toLowerCase();if(filter.search&&!hay.includes(filter.search.toLowerCase()))return false;for(const key of ['name','phone','email','id','unit','tower','floor','tags','subSource'])if(filter[key]&&!String(r[key]||'').toLowerCase().includes(filter[key].toLowerCase()))return false;for(const key of ['owner','coOwner','source','project','currentProject','configuration','purpose','eoi','investor','wtTag'])if(filter[key]&&(key==='configuration'?(r.configuration||r.bhk):r[key])!==filter[key])return false;if(filter.status&&(view==='Leads'?statusOf(r):r.status)!==filter.status)return false;const created=(r.createdAt||'').slice(0,10);if(filter.createdFrom&&created<filter.createdFrom)return false;if(filter.createdTo&&created>filter.createdTo)return false;const follow=(task(r)?.due||'').slice(0,10);if(filter.followFrom&&follow<filter.followFrom)return false;if(filter.followTo&&follow>filter.followTo)return false;if(filter.missed==='yes'&&!overdue(r))return false;return true;}
function listToolbar(){const count=Object.values(filter).filter(Boolean).length;return `<div class="list-toolbar"><input id="quick-search" aria-label="Search records" placeholder="Search name, phone, project or ID" value="${esc(filter.search||'')}"><span>${count?`${count} active filters`:''}</span>${button('Filters','filters')}${button('Reset','clearFilters','','secondary')}<label>Rows per page <select id="page-size">${[5,10,20,50].map(n=>`<option ${pageSize===n?'selected':''}>${n}</option>`).join('')}</select></label></div>`;}
function pagination(total){const pages=Math.max(1,Math.ceil(total/pageSize));page=Math.min(page,pages);return `<div class="pagination"><span>Total records: ${total}</span><div>${button('‹ Previous','prev','','secondary')}<span>Page ${page} / ${pages}</span>${button('Next ›','next','','secondary')}</div></div>`;}
function leadRows(rows,compact=false){return rows.length?rows.map(l=>{const events=store.events.filter(e=>e.leadId===l.id),t=task(l);return `<article class="lead-row"><div><button class="record-name" data-action="leadDetail" data-id="${l.id}">${esc(l.name)}</button><p>Phone No.: ${esc(l.phone)}<br>E-mail: ${esc(l.email||'—')}<br>Project: ${esc(l.project||'—')}</p><div class="inline-badges">${statusBadge(statusOf(l))}${l.tags?`<span class="tag">${esc(l.tags)}</span>`:''}</div><small>${esc(l.configuration||l.requirement||'Requirement pending')} · ${l.budget?money(l.budget):'Budget pending'}</small></div><div class="record-notes"><strong>Notes</strong>${events.slice(0,2).map(e=>`<p><small>${fmt(e.at)}</small><br>${esc(e.notes)}</p>`).join('')||'<p>No notes</p>'}</div><div class="record-meta"><strong>ID: ${esc(l.id)}</strong><p>Created Date: ${fmt(l.createdAt)}<br>Updated Date: ${fmt(l.updatedAt)}<br><span class="${overdue(l)?'overdue':''}">Next Follow-Up Date: ${t?fmt(t.due):'Closed'}</span><br>Source / Sub-source: ${esc(l.source)} / ${esc(l.subSource||'—')}<br>User: ${esc(l.owner)}${l.coOwner?'<br>Co-assigned: '+esc(l.coOwner):''}</p><div class="row-actions">${button('Edit','editLead',l.id)}${active(l)?button('Call','call',l.id):''}${button('WhatsApp','message',l.id)}${!compact?button('Register to Builder','builder',l.id)+button('Add to Inventory','leadInventory',l.id):''}${button('History','leadDetail',l.id)}</div></div></article>`;}).join(''):empty();}
function leadsPage(){const base=allLeads(),rows=base.filter(matches).filter(l=>statusFilter==='All'||statusOf(l)===statusFilter);const pages=Math.max(1,Math.ceil(rows.length/pageSize));page=Math.min(page,pages);return title('Leads','',button('Add Lead','newLead','','primary'))+statusChips(base)+`<section class="surface">${listToolbar()}${leadRows(rows.slice((page-1)*pageSize,page*pageSize))}${pagination(rows.length)}</section>`;}
function sourceRows(rows){return rows.map(r=>`<article class="lead-row"><div><button class="record-name" data-action="sourceEdit" data-id="${r.id}">${esc(r.kind==='Sellers'?'Seller':'Owner')}: ${esc(r.name)}</button><p>Phone No.: ${esc(r.phone)}<br>Co-owner: ${esc(r.coOwner||'—')}<br>Tenant: ${esc(r.tenant||'—')}<br>Project: ${esc(r.project||'—')}</p>${statusBadge(r.status||'Initial')}</div><div><strong>Notes</strong><p>${esc(r.notes||'No notes yet')}</p><p>Unit: ${esc(r.unit||'—')} · Tower: ${esc(r.tower||'—')}<br>Floor: ${esc(r.floor||'—')} · Series: ${esc(r.series||'—')}<br>${esc(r.bhk||'—')} · ${r.area||0} sq ft</p></div><div><strong>ID: ${r.id}</strong><p>Assigned: ${esc(r.owner)}<br>Updated: ${fmt(r.updatedAt||r.createdAt)}</p><div class="row-actions">${button('Edit','sourceEdit',r.id)}${button('WhatsApp','sourceMessage',r.id)}${r.leadId?button('Open '+r.leadId,'leadDetail',r.leadId):button('Add as a Lead','convertLead',r.id)}${r.inventoryId?button('Open '+r.inventoryId,'inventoryDetail',r.inventoryId):button('Add as an Inventory','convertInventory',r.id)}</div></div></article>`).join('')||empty();}
function sourcesPage(){const base=store.sources.filter(r=>r.kind===view&&visible(r)),rows=base.filter(matches).filter(r=>statusFilter==='All'||(r.status||'Initial')===statusFilter);page=Math.min(page,Math.max(1,Math.ceil(rows.length/pageSize)));return title(view,'',button('Add '+(view==='Sellers'?'Seller':'Data'),'newSource',view,'primary'))+statusChips(base,view)+`<section class="surface">${listToolbar()}${sourceRows(rows.slice((page-1)*pageSize,page*pageSize))}${pagination(rows.length)}</section>`;}
function smallTable(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table>${rows.length?'':empty()}</div>`;}
function panel(name,body,extra=''){return `<section class="surface"><div class="panel-title"><h2>${name}</h2>${extra}</div>${body}</section>`;}
function summaryBreakdown(key){const groups={};allLeads().forEach(l=>{const k=l[key]||'Unassigned';groups[k]=(groups[k]||0)+1;});return `<div class="breakdown">${Object.entries(groups).map(([k,n],i)=>`<div><span>${esc(k)}</span><div class="bar"><i style="width:${n/Math.max(1,allLeads().length)*100}%;background:${['#ad69c0','#268daf','#ed9972'][i%3]}"></i></div><strong>${n}</strong></div>`).join('')}</div>`;}
function dashboard(){const ls=allLeads(),missed=ls.filter(overdue),visits=store.visits.filter(v=>visible(v)&&v.status==='Scheduled');let html=title('Welcome, '+(role==='Manager'?'Manager':role)+'!','',`<span class="muted">${day(clock)}</span>`);html+=`<div class="tabs dashboard-tabs">${[['D1','Overview'],['D2','Calls & Daily Leads'],['D3','Site Visits'],['D4','Missed Follow Ups']].map(([d,label])=>`<button data-dashboard="${d}" class="${dash===d?'selected':''}">${d} · ${label}</button>`).join('')}</div>`;
 if(dash==='D1')html+=`<div class="dashboard-grid">${panel('Sources',summaryBreakdown('source'))}${panel('Projects',summaryBreakdown('project'))}${panel('Total Sales Revenue',`<div class="revenue"><strong>${money(ls.filter(l=>l.stage==='Won').reduce((a,l)=>a+(l.saleValue||0),0))}</strong><span>${ls.filter(l=>l.stage==='Won').length} booked opportunities</span><p>Calculated from this demo’s records</p></div>`)}</div>`+statusChips(ls)+panel('Live Initials',smallTable(['Lead ID','Name','Phone Number','User','Project','Source','Created Time'],ls.filter(l=>statusOf(l)==='Initial').map(l=>[esc(l.id),button(esc(l.name),'leadDetail',l.id,'text-button'),esc(l.phone),esc(l.owner),esc(l.project),esc(l.source),fmt(l.createdAt)])));
 if(dash==='D2'){const callEvents=store.events.filter(e=>e.type.startsWith('Call:')&&ls.some(l=>l.id===e.leadId));html+=`<div class="dashboard-grid">${panel('Daily Leads',`<div class="revenue"><strong>${ls.filter(l=>l.createdAt.slice(0,10)===today()).length}</strong><span>Created on demo date</span></div>`)}${panel('Connected Calls',`<div class="revenue"><strong>${callEvents.filter(e=>e.type==='Call: Connected').length}</strong><span>Calls recorded this session</span></div>`)}${panel('Not Connected Calls',`<div class="revenue"><strong>${callEvents.filter(e=>e.type!=='Call: Connected').length}</strong><span>Includes RNR attempts</span></div>`)}</div>`+panel('Call Activity',smallTable(['Lead','Outcome','Notes','Time'],callEvents.map(e=>[button(esc(byId(e.leadId).name),'leadDetail',e.leadId,'text-button'),esc(e.type),esc(e.notes),fmt(e.at)])));}
 if(dash==='D3')html+=panel('Stage Up',smallTable(['Lead','Status','User','Next Follow-Up'],ls.filter(l=>['Verified','Site Visit Scheduled','Site Visit Done'].includes(statusOf(l))).map(l=>[button(esc(l.name),'leadDetail',l.id,'text-button'),statusBadge(statusOf(l)),esc(l.owner),fmt(task(l)?.due)])))+panel('Site Visits',smallTable(['Lead','Project','Date','User','Action'],visits.map(v=>[button(esc(byId(v.leadId).name),'leadDetail',v.leadId,'text-button'),esc(v.project),fmt(v.when),esc(v.owner),button('Mark SVD','completeVisit',v.leadId)])));
 if(dash==='D4')html+=panel('Missed Follow Ups',smallTable(['Lead','Status','User','Follow-Up Date','Action'],missed.map(l=>[button(esc(l.name),'leadDetail',l.id,'text-button'),statusBadge(statusOf(l)),esc(l.owner),`<span class="overdue">${fmt(task(l).due)}</span>`,button('Record Follow-Up','followup',l.id)])));
 return html;
}
function recordRows(key){let rows=key==='inventory'?store.inventory:store.modules[key];if(role!=='Manager'&&['sales','incentives','salescrm','leaves','attendance','reimbursement','digitalTasks','allotment'].includes(key))rows=rows.filter(visible);if(key==='notices'&&noticeCategory!=='All')rows=rows.filter(r=>r.category===noticeCategory);return rows;}
function modulePage(key,nested=false){const spec=MODULES[key],rows=recordRows(key);let html=title(spec.title,'Demo records and approvals stay in this session.',button('Add '+spec.singular,'newRecord',key,'primary')+button('Export CSV','export',key));if(key==='notices')return html+`<div class="tabs">${['All','HR','Management','Marketing','Admin'].map(c=>`<button data-category="${c}" class="${noticeCategory===c?'selected':''}">${c}</button>`).join('')}</div><div class="notice-list">${rows.map(r=>`<article class="surface notice"><div class="notice-category">${r.category}</div><div><h2>${esc(r.title)}</h2><p>${esc(r.body)}</p><small>Updated ${fmt(r.updatedAt||r.createdAt)}</small>${button('Edit','editRecord',key+'|'+r.id)}</div></article>`).join('')||empty()}</div>`;
 const fields=spec.fields.filter(f=>!['notes','body','usps'].includes(f.key)).slice(0,8);html+=`<section class="surface">${smallTable(['ID',...fields.map(f=>esc(f.label)),'Actions'],rows.map(r=>[esc(r.id),...fields.map(f=>f.key==='status'?statusBadge(r[f.key]):esc(f.type==='number'?Number(r[f.key]||0).toLocaleString('en-IN'):r[f.key]||'—')),button('View / Edit','editRecord',key+'|'+r.id)]))}<div class="pagination">Total records: ${rows.length}</div></section>`;return html;}
function processPage(){const p=PROCESS[processTab];return title('Processes','Standard procedures shown in the reference walkthrough.')+`<div class="tabs">${Object.keys(PROCESS).map(t=>`<button data-process="${t}" class="${processTab===t?'selected':''}">${t}</button>`).join('')}</div><section class="surface process-surface"><h2>${processTab==='Transferred'?'LEADS TRANSFER':processTab.toUpperCase()} PROCESS</h2><div class="flow">${p.steps.map((s,i)=>`<div class="flow-step"><span>${i+1}</span><p>${esc(s)}</p></div>${i<p.steps.length-1?'<div class="flow-arrow">↓</div>':''}`).join('')}</div><p class="muted">${esc(p.source)}</p><div class="execute-process"><label>Choose lead<select id="process-lead">${selectOptions(allLeads().filter(active).map(l=>[l.id,l.id+' · '+l.name]))}</select></label>${button('Run '+processTab+' workflow','runProcess','','primary')}</div><p class="small-note">WhatsApp is a local draft. Transfer permissions are simulated with the Manager view.</p></section>`;}
function reportPage(){const ls=allLeads(),modes=['Logs','Site Visits','Status','Missed Follow Ups','Today Uploaded Activity'];let rows=[];if(reportTab==='Status'){rows=users().map(u=>[esc(u),...STATUS.map(st=>{const n=ls.filter(l=>l.owner===u&&statusOf(l)===st).length;return n?button(String(n),'reportDrill',u+'|'+st,'text-button'):'0';}),ls.filter(l=>l.owner===u).length]);return title('Reports','Counts link back to matching lead records.',button('Export CSV','export','leadReport'))+`<div class="tabs">${modes.map(m=>`<button data-report="${m}" class="${reportTab===m?'selected':''}">${m}</button>`).join('')}</div>`+panel('Status by User',smallTable(['User',...STATUS,'Total'],rows));}
 let body='';if(reportTab==='Site Visits')body=smallTable(['Lead','Project','User','Date','Status'],store.visits.filter(visible).map(v=>[button(esc(byId(v.leadId).name),'leadDetail',v.leadId,'text-button'),esc(v.project),esc(v.owner),fmt(v.when),statusBadge(v.status)]));else if(reportTab==='Missed Follow Ups')body=leadRows(ls.filter(overdue),true);else if(reportTab==='Today Uploaded Activity')body=leadRows(ls.filter(l=>l.createdAt.slice(0,10)===today()),true);else body=smallTable(['Lead / Record','Activity','Notes','Time'],store.events.filter(e=>role==='Manager'||ls.some(l=>l.id===e.leadId)).map(e=>[e.leadId?button(esc(e.leadId),'leadDetail',e.leadId,'text-button'):'Module record',esc(e.type),esc(e.notes),fmt(e.at)]));return title('Reports','Live results from demo records and event history.',button('Export CSV','export','leadReport'))+`<div class="tabs">${modes.map(m=>`<button data-report="${m}" class="${reportTab===m?'selected':''}">${m}</button>`).join('')}</div>`+panel(reportTab,body);}
function knowledgePage(){return title('Knowledge Base','Project and inventory details for the sales conversation.')+`<div class="project-cards">${store.modules.projects.map(p=>`<article class="surface project-card"><span class="tag">${esc(p.location)}</span><h2>${esc(p.name)}</h2><dl><div><dt>Configuration</dt><dd>${esc(p.config)}</dd></div><div><dt>Land</dt><dd>${p.land} acres</dd></div><div><dt>No. of Units</dt><dd>${p.units}</dd></div><div><dt>Status</dt><dd>${esc(p.status)}</dd></div></dl><h3>USPs</h3><p>${esc(p.usps)}</p>${button('View Inventory','projectInventory',p.name)}${button('View Leads','projectLeads',p.name)}</article>`).join('')}</div>`;}
function bulkPage(kind){if(kind==='Bulk Upload')return title(kind,'Upload contacts into Sellers or Data. The import is validated before saving.')+`<section class="surface padded"><div class="form-grid">${field('Destination','importKind','Data','text',true,['Data','Sellers'])}<label class="field"><span>CSV file</span><input type="file" id="csv-file" accept=".csv,text/csv"></label></div><p>Headers: <code>name,phone,owner,project,unit,configuration,area</code>. Only name and phone are required. Limit: 500 rows.</p>${button('Download sample CSV','csvSample')}<div id="import-preview" class="import-preview"></div></section>`;
 const source=kind==='Bulk Data Transfer',rows=source?store.sources:allLeads().filter(active);return title(kind,source?'Transfer selected source records between users.':'Update selected active leads together, with a recorded reason.')+`<section class="surface"><div class="list-toolbar">${button('Select all','selectAll')}${button('Clear selection','clearSelection')}${button('Configure update','bulkConfigure',source?'source':'lead','primary')}</div>${smallTable(['Select','ID','Name','User','Status'],rows.map(r=>[`<input type="checkbox" name="bulk-id" aria-label="Select ${esc(r.name)}" value="${r.id}">`,esc(r.id),esc(r.name),esc(r.owner),statusBadge(source?r.status||'Initial':statusOf(r))]))}</section>`;}
function costSheet(){return title('Buyer-Seller Cost Sheet','Illustrative arithmetic using the rates you enter; no tax rules are inferred.')+`<section class="surface padded"><form id="cost-form"><div class="form-grid">${field('Project','project','','text',true,projects())}${field('Configuration','configuration','','text',true,['1 BHK','2 BHK','3 BHK','Villa','Plot'])}${field('SQFT','sqft','','number',true)}${field('Buyer / Seller','party','Buyer','text',true,['Buyer','Seller'])}${field('Sale Value (INR)','saleValue','','number',true)}${field('GST (%) — enter applicable rate','gst','0','number',true)}${field('Brokerage (%)','brokerage','1','number',true)}${field('Additional Amount (INR)','additional','0','number',true)}${field('Note','note','','textarea')}</div><button class="primary" type="submit">Get Cost Sheet</button></form><div id="cost-result"></div></section>`;}
