function render(){let html;if(view==='Dashboard')html=dashboard();else if(view==='Leads')html=leadsPage();else if(['Sellers','Data'].includes(view))html=sourcesPage();else if(view==='Process')html=processPage();else if(view==='Reports')html=reportPage();else if(view==='Settings')html=settingsPage();else if(view==='Knowledge')html=knowledgePage();else if(view==='Workflow')html=workflowPage();else if(view==='Follow Ups')html=title('Follow Ups','All open follow-ups for the selected user.')+panel('Working queue',smallTable(['Lead','Status','User','Due','Action'],allLeads().filter(l=>task(l)).sort((a,b)=>Date.parse(task(a).due)-Date.parse(task(b).due)).map(l=>[button(esc(l.name),'leadDetail',l.id,'text-button'),statusBadge(overdue(l)?'Overdue':statusOf(l)),esc(l.owner),fmt(task(l).due),button('Record Follow-Up','followup',l.id)])));else html=modulePage(view);shell(html);bindPage();}
