function leadDetail(id){const l=byId(id);if(!l)return;const t=task(l),visit=store.visits.find(v=>v.leadId===id&&v.status==='Scheduled');openDialog('Lead '+l.id,l.name,`<div class="lead-summary">${statusBadge(statusOf(l))}<span>${esc(l.phone)}</span><span>${esc(l.owner)}</span><span>${esc(l.project||'No project selected')}</span></div><dl class="detail-facts"><div><dt>Configuration</dt><dd>${esc(l.configuration||l.requirement||'—')}</dd></div><div><dt>Budget</dt><dd>${money(l.budget)}</dd></div><div><dt>RNR count</dt><dd>${l.rnrCount||0} / 4</dd></div><div><dt>Next Follow-Up</dt><dd>${t?fmt(t.due):'Closed'}</dd></div><div><dt>Source</dt><dd>${esc(l.source)}${l.origin?' · '+esc(l.origin.id):''}</dd></div><div><dt>Co-assigned To</dt><dd>${esc(l.coOwner||'—')}</dd></div></dl><div class="actions wrap">${button('Edit Lead','editLead',id)}${active(l)?button('Log Call','call',id,'primary')+button('Follow-Up','followup',id)+button('Transfer','transfer',id)+(['Qualified','Site Visit Done'].includes(l.stage)?button('Schedule Site Visit','scheduleVisit',id):'')+(visit?button('Mark Visit Done','completeVisit',id):'')+button('Close Lead','close',id):''}${button('WhatsApp Draft','message',id)}${button('Register to Builder','builder',id)}${button('Add to Inventory','leadInventory',id)}</div>${visit?`<p class="info">Visit: ${esc(visit.project)} · ${fmt(visit.when)}</p>`:''}<h3>Lead History</h3><div class="timeline">${store.events.filter(e=>e.leadId===id).map(e=>`<article><strong>${esc(e.type)}</strong><p>${esc(e.notes)}</p><small>${fmt(e.at)}</small></article>`).join('')}</div><h3>Builder Registrations</h3>${store.registrations.filter(r=>r.leadId===id).map(r=>`<p>${esc(r.builder)} · ${esc(r.project)} · ${r.status}</p>`).join('')||'<p class="muted">None recorded</p>'}`,true);}
function addLead(){form('Add Lead','Fields marked * are required. A first-call task is created automatically.',field('Name','name','','text',true)+field('Phone No.','phone','','tel',true)+field('E-mail','email','','email')+field('Current Project','currentProject','','text',false,projects())+field('Interested Project','project','','text',false,projects())+field('Status','status','Initial','text',true,['Initial'])+field('Source','source','Manual','text',true,SOURCES)+field('Sub-Source','subSource')+field('Configuration','configuration','','text',false,['1 BHK','2 BHK','3 BHK','4 BHK','Villa','Plot'])+field('Budget (INR)','budget','0','number')+field('Size','size')+field('Purpose','purpose','Self','text',false,['Self','Investment'])+nextField()+field('Assigned To','owner',role==='Manager'?'':role,'text',false,users())+noteField(),d=>{if(Date.parse(d.next)<=Date.parse(clock))throw new Error('Follow-up date must be in the future.');const r=applyCRM(store,{type:'createLead',data:{...d,requirement:d.configuration}},clock,role);const l=r.state.leads.find(l=>l.id===r.resultId);Object.assign(l,{status:'Initial',configuration:d.configuration,currentProject:d.currentProject,project:d.project,originalProject:d.currentProject,budget:Number(d.budget)||0,size:d.size,purpose:d.purpose,subSource:d.subSource});r.state.tasks.find(t=>t.leadId===l.id&&t.status==='Open').due=new Date(d.next).toISOString();r.state.events[0].notes+=' '+d.notes;store=r.state;modal.close();render();notify(r.message);leadDetail(r.resultId);});}
function editLead(id){const l=byId(id),t=task(l);form('Edit Lead: '+id,'Use site-visit and closure actions for those status transitions.',field('Name','name',l.name,'text',true)+field('Phone No.','phone',l.phone,'tel',true)+field('E-mail','email',l.email,'email')+field('Original Project','originalProject',l.originalProject||l.project,'text',false,projects())+field('Current Project','currentProject',l.currentProject,'text',false,projects())+field('Interested Project','project',l.project,'text',false,projects())+field('Status','status',statusOf(l),'text',true,STATUS)+field('Configuration','configuration',l.configuration||'2 BHK','text',true,['1 BHK','2 BHK','3 BHK','4 BHK','Villa','Plot'])+field('Budget (INR)','budget',l.budget,'number',true)+field('Size','size',l.size)+field('No. of RNR','rnrCount',l.rnrCount||0,'number')+field('EOI','eoi',l.eoi||'No','text',false,['Yes','No'])+field('Next Follow-Up Date','next',local(t?.due||later(24)),'datetime-local',active(l))+field('Expected Closure Date','expectedClosure',l.expectedClosure,'date')+field('Purpose','purpose',l.purpose||'Self','text',false,['Self','Investment'])+field('Urgency','urgency',l.urgency,'text',false,['Immediate','Within 1 month','1–3 months','3–6 months','Exploring'])+field('Investor','investor',l.investor||'No','text',false,['Yes','No'])+field('Assigned To','owner',l.owner,'text',true,users())+field('Co-Assigned To','coOwner',l.coOwner,'text',false,users())+field('Source','source',l.source,'text',true,[...new Set([...SOURCES,l.source])])+field('Sub-Source','subSource',l.subSource)+field('WT Tag','wtTag',l.wtTag||'Warm','text',false,['Hot','Warm','Cold'])+field('Tags','tags',l.tags)+field('Not Interested Reason','reason',l.reason,'text',false,REASONS)+noteField(),d=>run({type:'editLead',leadId:id,data:d},true));}
function leadAction(type,id){const l=byId(id);if(!l)return;let fields='',name='';if(type==='call'){name='Log Call';fields=field('Call Outcome','outcome','Connected','text',true,['Connected','Not connected','RNR'])+nextField()+`<div id="qualify-fields" class="full form-grid">${field('Configuration / Requirement','requirement',l.requirement,'text',true)}${field('Budget (INR)','budget',l.budget,'number',true)}${field('Interested Project','project',l.project,'text',true,projects())}${field('Current Project','currentProject',l.currentProject,'text',false,projects())}${field('Urgency','urgency',l.urgency||'1–3 months','text',true,['Within 1 month','1–3 months','3–6 months','Exploring'])}</div><div class="full info">RNR attempts recorded: ${l.rnrCount||0}. The fourth unanswered attempt marks RNR. Use the Process tab for the reference schedule.</div>`+noteField();}
 if(type==='followup'){name='Record Follow-Up';fields=nextField()+noteField();}
 if(type==='scheduleVisit'){name='Site Visit Scheduled';fields=field('Project','project',l.project,'text',true,projects())+field('Site Visit Scheduled Date','when',local(later(24)),'datetime-local',true)+nextField(later(26))+noteField();}
 if(type==='completeVisit'){name='Site Visit Done';fields=nextField()+noteField();}
 if(type==='transfer'){name='Leads Transfer';fields=field('Assigned To','owner','','text',true,users().filter(n=>n!==l.owner))+noteField();}
 if(type==='close'||type==='lost'){name=type==='lost'?'Lost Lead Process':'Close Lead';fields=field('Disposition','outcome',type==='lost'?'Not Interested':'Booked','text',true,['Booked','Not Interested','Cancelled','Duplicate'])+`<div id="won-fields" class="full form-grid">${field('Sale Value (INR)','saleValue',l.budget,'number',true)}${field('Incentive (INR)','incentives','0','number',true)}${field('Closure Date','closedDate',today(),'date',true)}</div><div id="lost-fields" class="full">${field('Not Interested Reason','reason',type==='lost'?'Lost Lead':'','text',true,REASONS)}</div>`+noteField();}
 form(name,l.name+' · '+id,fields,d=>{if(type==='lost'||type==='close'){const reason=d.reason;const converted={'Not Looking for Any Property':'Not interested','Budget Mismatch':'Budget mismatch','Location Mismatch':'Location mismatch','Purchased Elsewhere':'Purchased elsewhere','Invalid Enquiry':'Invalid enquiry','Lost Lead':'Other',Other:'Other'};const result=applyCRM(store,{type:'close',leadId:id,data:{...d,outcome:d.outcome==='Booked'?'Won':'Lost',reason:converted[d.reason]}},clock,role);const saved=result.state.leads.find(x=>x.id===id);saved.reason=reason||'';saved.status=d.outcome;if(reason==='Lost Lead'){saved.lostReason='Lost Lead';result.state.drafts.unshift({id:'LOST-'+id,leadId:id,message:'LOST | '+id+' | '+l.name+' | '+d.notes,status:'Draft only',createdAt:clock});}store=result.state;modal.close();render();notify(result.message);leadDetail(id);}else run({type,leadId:id,data:d},true);});
 const toggle=(selectName,blocks)=>{const el=modal.querySelector(`[name=${selectName}]`);const change=()=>blocks.forEach(([selector,when])=>{const container=modal.querySelector(selector),enabled=when(el.value);container.hidden=!enabled;container.querySelectorAll('input,select,textarea').forEach(x=>x.disabled=!enabled);});el.addEventListener('change',change);change();};if(type==='call')toggle('outcome',[['#qualify-fields',v=>v==='Connected']]);if(type==='close'||type==='lost')toggle('outcome',[['#won-fields',v=>v==='Booked'],['#lost-fields',v=>v!=='Booked']]);}
function sourceForm(id,kind){const r=id?store.sources.find(x=>x.id===id):{kind,name:'',phone:'',owner:role==='Manager'?users()[0]:role,status:'Initial'};form((id?'Edit ':'Add ')+(r.kind==='Sellers'?'Seller':'Data'),id||'Create a source record',field('Owner / Seller Name','name',r.name,'text',true)+field('Phone No.','phone',r.phone,'tel',true)+field('Co-owner','coOwner',r.coOwner)+field('Tenant','tenant',r.tenant)+field('Project','project',r.project,'text',false,projects())+field('Unit Number','unit',r.unit)+field('Building / Tower','tower',r.tower)+field('Floor','floor',r.floor)+field('Series','series',r.series)+field('Configuration','bhk',r.bhk,'text',false,['1 BHK','2 BHK','3 BHK','4 BHK','Villa','Plot'])+field('Sq. Footage','area',r.area||0,'number')+field('Owner Number Status','status',r.status||'Initial','text',true,SELLER_STATUS)+field('Assigned To','owner',r.owner,'text',true,users())+noteField(),d=>{if(id)run({type:'sourceEdit',sourceId:id,data:d});else{const result=applyCRM(store,{type:'createSource',data:{...d,kind:r.kind}},clock,role);Object.assign(result.state.sources.find(x=>x.id===result.resultId),{status:d.status,notes:d.notes,coOwner:d.coOwner,tenant:d.tenant,series:d.series,createdAt:clock});store=result.state;modal.close();render();notify(result.message);}});}
function choicesFor(f){if(f.type==='select')return f.choices;if(f.type==='agent')return users();if(f.type==='project')return projects();if(f.type==='lead')return allLeads().map(l=>[l.id,l.id+' · '+l.name]);if(f.type==='asset')return store.modules.assets.map(r=>[r.id,r.name+' · '+r.code]);if(f.type==='sale')return store.modules.sales.map(r=>[r.id,r.id+' · '+r.project]);return null;}
