function filterDialog(){const lead=view==='Leads';const group=(name,fields)=>`<details open class="filter-group"><summary>${name}</summary><div class="form-grid">${fields}</div></details>`;form('Filter',`${view} · apply or reset filters`,group('Basic Filters',field('Lead ID / Record ID','id',filter.id)+field('Name','name',filter.name)+field('Number','phone',filter.phone)+field('E-mail','email',filter.email))+group('Lead Filters',field('Status','status',filter.status,'text',false,lead?STATUS:SELLER_STATUS)+field('Assigned To','owner',filter.owner,'text',false,users())+field('Co-Assigned To','coOwner',filter.coOwner,'text',false,users())+field('Source','source',filter.source,'text',false,SOURCES)+field('Sub-Source','subSource',filter.subSource))+group('Project Filters',field('Project','project',filter.project,'text',false,projects())+field('Current Project','currentProject',filter.currentProject,'text',false,projects())+field('Configuration','configuration',filter.configuration,'text',false,['1 BHK','2 BHK','3 BHK','4 BHK','Villa','Plot']))+group('Additional Filters',field('Unit Number','unit',filter.unit)+field('Building / Tower','tower',filter.tower)+field('Floor','floor',filter.floor)+field('Missed Follow-Up only','missed',filter.missed,'text',false,[['yes','Yes']]))+group('Date Filters',field('Created Date From','createdFrom',filter.createdFrom,'date')+field('Created Date To','createdTo',filter.createdTo,'date')+field('Follow-Up From','followFrom',filter.followFrom,'date')+field('Follow-Up To','followTo',filter.followTo,'date'))+group('Tag Filters',field('Purpose','purpose',filter.purpose,'text',false,['Self','Investment'])+field('EOI','eoi',filter.eoi,'text',false,['Yes','No'])+field('Investor','investor',filter.investor,'text',false,['Yes','No'])+field('WT Tag','wtTag',filter.wtTag,'text',false,['Hot','Warm','Cold'])+field('Tags','tags',filter.tags)),d=>{filter=d;page=1;modal.close();render();},'Apply');}
function messageForm(id,isSource=false){const r=isSource?store.sources.find(r=>r.id===id):byId(id);form('WhatsApp Draft','Draft only. This demo never sends messages.',field('Message','message',`Hello ${r.name}, following up on your property enquiry${r.project?' for '+r.project:''}. Reference: ${r.id}.`,'textarea',true),d=>run({type:'draftMessage',leadId:isSource?null:id,data:d}),'Save Draft',false);}
