function conversion(id,target){const r=store.sources.find(x=>x.id===id);if(target==='Lead'){form('Add as a Lead',`${r.name} · ${r.id}`,`<div class="full info">The new lead will retain its source link and be assigned to ${esc(r.owner)}. An existing conversion cannot be duplicated.</div>`,()=>run({type:'convert',sourceId:id,data:{target}},true),'Convert');return;}const fields=field('Project','project',r.project,'text',true,projects())+field('Unit','unit',r.unit,'text',true)+field('Configuration','bhk',r.bhk,'text',true,['1 BHK','2 BHK','3 BHK','4 BHK','Villa','Plot'])+field('Area (sq ft)','area',r.area,'number',true)+field('Asking Price (INR)','price','','number',true)+field('Tower','tower',r.tower)+field('Floor','floor',r.floor);form('Add as an Inventory',`${r.name} · ${r.id}`,fields,d=>run({type:'convert',sourceId:id,data:{...d,target}}),'Convert');}
function leadInventory(id){const l=byId(id);const spec=MODULES.inventory;form('Add to Inventory','Use when the lead also has a property to sell. Source lead is preserved.',spec.fields.filter(f=>!['seller','owner','status'].includes(f.key)).map(f=>field(f.label,f.key,f.key==='project'?l.project:'',f.type==='project'?'text':f.type,f.required,choicesFor(f))).join(''),d=>run({type:'leadInventory',leadId:id,data:d}));}
function searchDialog(){openDialog('Leads - Search Leads','Search by lead ID, name or number.',`<input id="search-dialog" aria-label="Search leads" placeholder="Lead ID, name or phone number"><div id="search-results"></div>`,true);modal.querySelector('input').addEventListener('input',e=>{const q=e.target.value.toLowerCase();modal.querySelector('#search-results').innerHTML=q?smallTable(['ID','Name','Phone','User'],allLeads().filter(l=>[l.id,l.name,l.phone].some(x=>x.toLowerCase().includes(q))).map(l=>[l.id,button(esc(l.name),'leadDetail',l.id,'text-button'),l.phone,l.owner])):'';});}
function exportCSV(rows,filename){if(!rows.length){notify('No records to export.');return;}const keys=[...new Set(rows.flatMap(Object.keys))].filter(k=>rows.every(r=>typeof r[k]!=='object'));const cell=v=>{const value=String(v??'');return '"'+(/^[=+@\-]/.test(value)?"'":'')+value.replace(/"/g,'""')+'"';};const content=[keys,...rows.map(r=>keys.map(k=>r[k]))].map(r=>r.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url);}
function configureBulk(source){const ids=[...document.querySelectorAll('[name=bulk-id]:checked')].map(x=>x.value);if(!ids.length){notify('Select at least one record.');return;}form('Configure '+(source?'Data Transfer':'Bulk Update'),`${ids.length} records selected`,field('Assign to User','owner','','text',source,users())+(source?'':field('New Source','source','','text',false,SOURCES)+field('Next Follow-Up Date','next','','datetime-local'))+noteField(),d=>{const action={type:source?'bulkTransfer':'bulkUpdate',ids,data:d};applyCRM(store,action,clock,role);pendingBulk=action;openDialog('Review bulk change',`${ids.length} records · no changes saved yet`,`<p>${esc(ids.join(', '))}</p><p>New user: ${esc(d.owner||'Unchanged')}<br>Source: ${esc(d.source||'Unchanged')}<br>Follow-up: ${d.next?fmt(d.next):'Unchanged'}</p><p>${esc(d.notes)}</p><div class="form-footer">${button('Cancel','dismiss')}${button('Apply to selected records','bulkCommit','','primary')}</div>`);},'Review');}
function bindPage(){const csv=document.querySelector('#csv-file');if(csv)csv.addEventListener('change',async e=>{const out=document.querySelector('#import-preview');try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw new Error('CSV must be smaller than 1 MB.');pendingCSV=parseCSV(await file.text());const kind=document.querySelector('[name=importKind]').value;applyCRM(store,{type:'importCSV',rows:pendingCSV,data:{kind}},clock,role);out.innerHTML=`<h3>${pendingCSV.length} validated records · ${esc(kind)}</h3>${smallTable(['Name','Phone','Owner','Project'],pendingCSV.slice(0,10).map(r=>[esc(r.name),esc(r.phone),esc(r.owner||users()[0]),esc(r.project)]))}${button('Import validated records','importCommit','','primary')}`;}catch(error){pendingCSV=[];out.textContent=error.message;}});
 const cost=document.querySelector('#cost-form');if(cost)cost.addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(cost));const sale=Number(d.saleValue),gst=Number(d.gst),brokerage=Number(d.brokerage),extra=Number(d.additional),sqft=Number(d.sqft);const out=document.querySelector('#cost-result');if(![sale,gst,brokerage,extra,sqft].every(Number.isFinite)||sale<=0||sqft<=0||[gst,brokerage,extra].some(x=>x<0)){out.textContent='Enter valid positive sale value and area, and non-negative rates.';return;}const tax=sale*gst/100,fee=sale*brokerage/100,total=d.party==='Buyer'?sale+tax+fee+extra:sale-tax-fee-extra;out.innerHTML=`<div class="cost-result"><h2>${esc(d.party)} Cost Sheet · ${esc(d.project)}</h2>${smallTable(['Item','Amount'],[['Sale Value',money(sale)],['Entered GST ('+gst+'%)',money(tax)],['Brokerage ('+brokerage+'%)',money(fee)],['Additional Amount',money(extra)],['Rate per sq ft',money(sale/sqft)],[d.party==='Buyer'?'Estimated Buyer Outlay':'Estimated Seller Net',`<strong>${money(total)}</strong>`]])}<p>Calculation only. Rates and applicability must be supplied and checked by your team.</p><p>${esc(d.note)}</p></div>`;});}
async function action(name,id){if(name==='dismiss'){modal.close();return;}if(name==='newLead')addLead();else if(name==='editLead')editLead(id);else if(name==='leadDetail')leadDetail(id);else if(['call','followup','transfer','scheduleVisit','completeVisit','close','lost'].includes(name))leadAction(name,id);else if(name==='newSource')sourceForm(null,id);else if(name==='sourceEdit')sourceForm(id);else if(name==='message'||name==='sourceMessage')messageForm(id,name==='sourceMessage');else if(name==='builder')builderForm(id);else if(name==='convertLead')conversion(id,'Lead');else if(name==='convertInventory')conversion(id,'Inventory');else if(name==='leadInventory')leadInventory(id);else if(name==='newRecord')recordForm(id);else if(name==='editRecord'){const [k,r]=id.split('|');recordForm(k,r);}else if(name==='inventoryDetail')recordForm('inventory',id);else if(name==='filters')filterDialog();else if(name==='clearFilters'){filter={};statusFilter='All';page=1;render();}else if(name==='next'){page++;render();}else if(name==='prev'){page=Math.max(1,page-1);render();}else if(name==='advance'){clock=later(24);render();notify('Demo clock advanced one day.');}else if(name==='theme'){dark=!dark;document.documentElement.dataset.theme=dark?'dark':'light';}else if(name==='notifications'){openDialog('Notifications','Calculated from the demo. No messages sent.',allLeads().filter(overdue).map(l=>`<p>${button(esc(l.name),'leadDetail',l.id,'text-button')} · Follow-up overdue ${fmt(task(l).due)}</p>`).join('')||empty('No overdue follow-ups.'),false);}else if(name==='profile'){openDialog('Account Profile','Demo identity only; no login credentials are stored.',`<h3>${esc(role)}</h3><p>Use the View as menu to simulate a user or Manager.</p><p>Role filters and action guards are prototype logic, not server-enforced security.</p>`,false);}else if(name==='runProcess'){const leadId=document.querySelector('#process-lead').value;if(!leadId){notify('Choose a lead first.');return;}leadAction(PROCESS[processTab].action,leadId);if(processTab==='RNR'){const el=modal.querySelector('[name=outcome]');el.value='RNR';el.dispatchEvent(new Event('change'));}}else if(name==='openProcess'){processTab=id;go('Process');}else if(name==='projectLeads'){go('Leads');filter.project=id;render();}else if(name==='projectInventory'){openDialog('Inventory',id,smallTable(['Unit','Configuration','Area','Price','Status'],store.inventory.filter(p=>p.project===id).map(p=>[button(esc(p.unit),'inventoryDetail',p.id,'text-button'),esc(p.bhk),p.area,money(p.price),statusBadge(p.status||'Available')])),true);}else if(name==='reportDrill'){const [user,status]=id.split('|');go('Leads');filter.owner=user;statusFilter=status;render();}else if(name==='export'){exportCSV(id==='leadReport'?allLeads():recordRows(id),'Home-Locator-'+id+'.csv');}else if(name==='csvSample'){exportCSV([{name:'Sample Buyer',phone:'9000000888',owner:users()[0],project:projects()[0],unit:'C-404',configuration:'2 BHK',area:1200}],'Home-Locator-Import-Sample.csv');}else if(name==='selectAll'||name==='clearSelection'){document.querySelectorAll('[name=bulk-id]').forEach(el=>el.checked=name==='selectAll');}else if(name==='bulkConfigure')configureBulk(id==='source');else if(name==='bulkCommit'){try{run(pendingBulk);pendingBulk=null;}catch(e){notify(e.message);}}else if(name==='importCommit'){try{const kind=document.querySelector('[name=importKind]').value;run({type:'importCSV',rows:pendingCSV,data:{kind}});pendingCSV=[];}catch(e){notify(e.message);}}else if(name==='reset'){openDialog('Reset demo?','This removes session changes and restores the fictional records.',`<div class="form-footer">${button('Cancel','dismiss')}${button('Reset sample data','resetConfirm','','primary')}</div>`,false);}else if(name==='resetConfirm'){clock=new Date().toISOString();store=seedCRM(clock);modal.close();role='Manager';go('Dashboard');}else if(name==='audit'){openDialog('Reference Audit & Coverage','Video evidence and demo boundaries.','<div id="audit-content">Loading…</div>',true);try{modal.querySelector('#audit-content').innerHTML=await(await fetch('audit.html')).text();}catch{modal.querySelector('#audit-content').textContent='Could not load the audit.';}}else if(name==='code'){openDialog('Executable workflow code','Core engine + extended CRM rules.','<pre id="source-code">Loading…</pre>',true);try{const files=await Promise.all(['workflow.js','crm.js'].map(async f=>'// '+f+'\n'+await(await fetch(f)).text()));modal.querySelector('pre').textContent=files.join('\n\n');}catch{modal.querySelector('pre').textContent='Open the source package to read the implementation.';}}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)go(b.dataset.view);else if(b.dataset.dashboard){dash=b.dataset.dashboard;go('Dashboard');}else if(b.dataset.status){statusFilter=b.dataset.status;if(view==='Dashboard')view='Leads';page=1;render();}else if(b.dataset.settings){settingsTab=b.dataset.settings;render();}else if(b.dataset.process){processTab=b.dataset.process;render();}else if(b.dataset.report){reportTab=b.dataset.report;render();}else if(b.dataset.category){noticeCategory=b.dataset.category;render();}else if(b.dataset.action)action(b.dataset.action,b.dataset.id);});
document.addEventListener('change',e=>{if(e.target.id==='role'){role=e.target.value;render();}else if(e.target.id==='page-size'){pageSize=Number(e.target.value);page=1;render();}});
document.addEventListener('input',e=>{if(e.target.id==='quick-search'){const pos=e.target.selectionStart;filter.search=e.target.value;page=1;render();const el=document.querySelector('#quick-search');el.focus();el.setSelectionRange(pos,pos);}});
render();
if(document.modelContext?.registerTool){const controller=new AbortController();const tools=[{name:'read_crm_summary',description:'Read visible demo lead counts, statuses and clock.',annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object.');return{view,role,clock,leads:allLeads().length,overdue:allLeads().filter(overdue).length,statuses:Object.fromEntries(STATUS.map(s=>[s,allLeads().filter(l=>statusOf(l)===s).length]))};}},{name:'start_lead_creation',description:'Open the Add Lead form without saving a record.',annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object.');addLead();return{opened:modal.open};}}];tools.forEach(t=>{try{Promise.resolve(document.modelContext.registerTool({...t,inputSchema:{type:'object',properties:{},additionalProperties:false}},{signal:controller.signal})).catch(()=>{});}catch{}});window.addEventListener('pagehide',()=>controller.abort(),{once:true});}

